<script setup lang="ts">
defineProps<{report:any;type:string;day:string;month:string;days:number}>()
const emit=defineEmits<{preview:[];excel:[];pdf:[];'update:type':[v:string];'update:day':[v:string];'update:month':[v:string];'update:days':[v:number]}>()
const types=[['daily','Daily report'],['monthly','Monthly report'],['upcoming-events','Upcoming events'],['unpaid-invoices','Unpaid invoices'],['delivery-due','Delivery due'],['status-summary','Status summary'],['client-summary','Client summary']]
const money=(n:number)=>new Intl.NumberFormat('en-TZ',{maximumFractionDigits:0}).format(Number(n)||0)+' TZS'
const label=(key:string)=>key.replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase())
const preferred=['record_number','client_name','record_date','event_date','status_name','client_name','grand_total_minor','paid_minor','payment_status','invoice_no','location']
const columns=(report:any)=>{const keys=Object.keys(report?.rows?.[0]||report?.summary?.[0]||{});return preferred.filter(key=>keys.includes(key)).concat(keys.filter(key=>!preferred.includes(key)&&!['id','status_id','currency','deleted_at','created_at','updated_at'].includes(key)).slice(0,5))}
</script>
<template><article class="controls"><label>Report type<select :value="type" @change="emit('update:type',($event.target as HTMLSelectElement).value)"><option v-for="t in types" :key="t[0]" :value="t[0]">{{t[1]}}</option></select></label><label v-if="type==='daily'">Date<input :value="day" type="date" @input="emit('update:day',($event.target as HTMLInputElement).value)"></label><label v-if="type==='monthly'">Month<input :value="month" type="month" @input="emit('update:month',($event.target as HTMLInputElement).value)"></label><label v-if="type==='upcoming-events'">Days ahead<input :value="days" type="number" @input="emit('update:days',Number(($event.target as HTMLInputElement).value))"></label><button @click="emit('preview')">Preview report</button></article><article v-if="report" class="preview"><header><div><small>PREVIEW</small><h2>{{report.title||report.type.replaceAll('-',' ')}}</h2><span>{{report.period}}</span></div><div><button @click="emit('excel')">Export Excel</button><button class="primary" @click="emit('pdf')">Save PDF</button></div></header><div class="summary" v-if="report.summary?.length"><span v-for="(s,i) in report.summary" :key="i"><b>{{s.status_name||s.client_name||'Total'}}</b><br>{{s.records||0}} orders · {{money(s.total_minor??s.grand_total_minor)}}</span></div><table><thead><tr><th v-for="key in columns(report)" :key="key">{{label(key)}}</th></tr></thead><tbody><tr v-for="(r,i) in report.rows" :key="r.id||i"><td v-for="key in columns(report)" :key="key">{{String(key.includes('minor')?money(Number(r[key])):r[key]??'—')}}</td></tr></tbody></table></article></template>
<style scoped>.controls,.preview{background:#fff;border:1px solid var(--border);border-radius:12px;padding:20px}.controls{display:flex;gap:14px;align-items:end}.controls label{display:grid;gap:6px;font-weight:700;font-size:12px}.controls input,.controls select{border:1px solid var(--border);padding:9px;border-radius:7px}.controls button,.primary{border:0;background:var(--brand);color:#fff;border-radius:7px;padding:10px 14px;font-weight:800;cursor:pointer}header{display:flex;justify-content:space-between}h2{margin:4px 0}.summary{display:flex;gap:9px;margin:18px 0}.summary span{background:#f4efe4;padding:9px;border-radius:7px}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:12px;border-bottom:1px solid #eee8dd}th{font-size:10px;color:var(--muted)}</style>
